func (t *TransmuterModule) countShadowRows(ctx context.Context, row *masterBindingRuntime, cursor int64) (int64, error) {
	shadowDB, err := t.connMgr.GetShadowDB(ctx, row.ShadowConnectionKey)
	if err != nil {
		return 0, err
	}
	var total int64
	pkIdent := quoteTransmuteIdent(row.ShadowPK)
	qt := fmt.Sprintf(`SELECT COUNT(*) FROM %s WHERE %s > ?`,
		quoteTransmuteQualified(row.ShadowSchema, row.ShadowTable), fmt.Sprintf("(%s)::bigint", pkIdent))
	err = shadowDB.WithContext(ctx).Raw(qt, cursor).Scan(&total).Error
	return total, err
}

